template<class T, class U, class Less = std::less<>>
std::size_t lowerBound(const std::vector<T>& items, const U& needle, Less less = {}) {
    std::size_t low = 0, high = items.size();
    while (low < high) {
        const auto middle = low + (high - low) / 2;
        if (less(items[middle], needle)) low = middle + 1;
        else high = middle;
    }
    return low;
}

def breadth_first_search(graph, start):
    distance = [-1] * len(graph)
    if not graph:
        return distance
    queue = [start]
    distance[start] = 0
    head = 0
    while head < len(queue):
        vertex = queue[head]
        head += 1
        for neighbor in graph[vertex]:
            if distance[neighbor] == -1:
                distance[neighbor] = distance[vertex] + 1
                queue.append(neighbor)
    return distance

import java.util.Arrays;

final class BreadthFirstExample {
    static int[] run(int[][] graph, int start) {
        int[] distance = new int[graph.length];
        Arrays.fill(distance, -1);
        if (graph.length == 0) return distance;
        int[] queue = new int[graph.length];
        int head = 0, tail = 1;
        queue[0] = start;
        distance[start] = 0;
        while (head < tail) {
            int vertex = queue[head++];
            for (int neighbor : graph[vertex]) {
                if (distance[neighbor] == -1) {
                    distance[neighbor] = distance[vertex] + 1;
                    queue[tail++] = neighbor;
                }
            }
        }
        return distance;
    }
}

def topological_sort(graph):
    degree = [0] * len(graph)
    for row in graph:
        for vertex in row:
            degree[vertex] += 1
    order = [v for v, incoming in enumerate(degree) if incoming == 0]
    head = 0
    while head < len(order):
        vertex = order[head]
        head += 1
        for neighbor in graph[vertex]:
            degree[neighbor] -= 1
            if degree[neighbor] == 0:
                order.append(neighbor)
    return order if len(order) == len(graph) else None

final class TopologicalExample {
    static int[] run(int[][] graph) {
        int[] degree = new int[graph.length], order = new int[graph.length];
        for (int[] row : graph) {
            for (int vertex : row) degree[vertex]++;
        }
        int head = 0, tail = 0;
        for (int vertex = 0; vertex < graph.length; ++vertex) {
            if (degree[vertex] == 0) order[tail++] = vertex;
        }
        while (head < tail) {
            for (int neighbor : graph[order[head++]]) {
                if (--degree[neighbor] == 0) order[tail++] = neighbor;
            }
        }
        return tail == graph.length ? order : null;
    }
}

